action.command:
for g in loto6 loto7; do curl -sS --max-time 20 "https://$g.thekyo.jp/data/$g.csv" | iconv -f SHIFT_JIS -t UTF-8 | node -e '
const g=process.argv[1]; const spec=g==="loto6"?{m:6,b:1,max:43}:{m:7,b:2,max:37};
let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{
 const lines=s.split(/\r?\n/).filter(l=>l.trim()!=="");
 const h=lines[0].split(",").map(x=>x.trim().toLowerCase());
 const idx=k=>h.indexOf(k);
 const nIdx=[...Array(spec.m)].map((_,i)=>idx(`第${i+1}数字`));
 const bIdx=spec.b===1?[idx("bonus数字")]:[idx("bonus数字1"),idx("bonus数字2")];
 const errs=[]; const seen=new Set(); let last=null, prevDate="";
 lines.slice(1).forEach((l,i)=>{const r=l.split(",").map(x=>x.trim()); const row=i+2;
  if(r.length!==h.length) errs.push(`row ${row}: ${r.length} fields vs ${h.length}`);
  const no=Number(r[0]); if(!Number.isInteger(no)||no<1) errs.push(`row ${row}: bad no ${r[0]}`);
  if(seen.has(no)) errs.push(`row ${row}: dup ${no}`); seen.add(no);
  const p=r[1].split(/[\/.-]/); const d=new Date(Date.UTC(+p[0],+p[1]-1,+p[2]));
  if(p.length!==3||p[0].length!==4||d.getUTCDate()!==+p[2]) errs.push(`row ${row}: bad date ${r[1]}`);
  const key=`${p[0]}-${p[1].padStart(2,"0")}-${p[2].padStart(2,"0")}`;
  const nums=[...nIdx,...bIdx].map(j=>r[j]); const ints=nums.map(Number);
  if(ints.some(n=>!Number.isInteger(n)||n<1||n>spec.max)) errs.push(`row ${row}: range ${nums}`);
  if(new Set(ints).size!==ints.length) errs.push(`row ${row}: dup numbers ${nums}`);
  const wd=d.getUTCDay(); const okWd=g==="loto6"?(wd===1||wd===4):(wd===5);
  if(!okWd) errs.push(`row ${row}: off-schedule ${key} wd=${wd}`);
  if(key<=prevDate) errs.push(`row ${row}: non-increasing date ${key}`); prevDate=key; last=[no,key];
 });
 console.log(g,"rows",lines.length-1,"last",last,"errors",errs.length); console.log(errs.slice(0,15).join("\n"));
});' $g; done
